+private struct SharedSidebarFloatingPanel<Panel: View>: ViewModifier {
+    let isEnabled: Bool
+    let isFloating: Bool
+    @Binding var state: FloatingPanelState?
+    let panel: Panel
+
+    @ViewBuilder
+    func body(content: Content) -> some View {
